// v101: new Today's Story originals, en and es. Released one per day per grade.
// Fields match stories64: id, grade, t, text, art, q, plus optional talk, coach, and release101 (0-based day).
const STORIES101={en:[],es:[]};
(function(){
// English
STORIES101.en.push({"id": "d101_en_0_01", "grade": 0, "t": "The Soft Hat", "text": "Mia has a hat. The hat is soft.\n\nThe wind is big. The hat can fly.\n\nDad holds the hat. Mia holds it too.\n\nThe hat stays on. The wind can play.", "art": "softHat", "release101": 0, "q": [["What is soft?", ["The hat", "The wind", "A rock"], 0], ["Who holds the hat with Mia?", ["Dad", "A duck", "A bug"], 0]], "talk": ["Who helped Mia keep her hat?", "What does the wind like to do?"], "coach": ["Warm-up: say hat, hold, wind slowly. Point to each word.", "Read the last two lines softly, like a calm wind."]});
STORIES101.en.push({"id": "d101_en_0_02", "grade": 0, "t": "Jam on the Pan", "text": "The pan is warm. Mom puts in jam.\n\nSam can see the jam. It is red and slow.\n\nMom puts the jam on a bun.\n\nSam has a bite. Mom has a bite.\n\nSweet jam. A good start.", "art": "jamPan", "release101": 1, "q": [["What color is the jam?", ["Red", "Blue", "Black"], 0], ["Where does the jam go?", ["On a bun", "In a hat", "On a shoe"], 0]], "talk": ["What did they put on the bun?", "Who had a bite?"], "coach": ["Warm-up: clap the words jam, pan, bun.", "Let your child smell or pretend to smell the jam on 'sweet jam.'"]});
STORIES101.en.push({"id": "d101_en_0_03", "grade": 0, "t": "A Bug on a Bud", "text": "A bud is on a stem. It is small.\n\nA bug sits on the bud.\n\nThe bug is still. The bud is still.\n\nA bee goes by. The bug does not hop.\n\nThe sun is warm. They rest.", "art": "bugBud", "release101": 2, "q": [["Where does the bug sit?", ["On a bud", "In a cup", "On a hat"], 0], ["What is the sun like?", ["Warm", "Cold", "Wet"], 0]], "talk": ["Who sat on the bud?", "What did the bug do when the bee went by?"], "coach": ["Warm-up: stretch bug, bud, bee. Notice they all start with b.", "Pause on 'still' and sit very still together for a moment."]});
STORIES101.en.push({"id": "d101_en_0_04", "grade": 0, "t": "The Wet Path", "text": "Rain was on the path. Drip, drip, drip.\n\nJen has red boots.\n\nJen hops to a puddle. Hop, hop.\n\nJen hops to the next. The path is fun.\n\nAt the end, Jen is home. The boots can rest.", "art": "wetPath", "release101": 3, "q": [["What is on the path?", ["Rain", "Snow", "Sand"], 0], ["What can rest at the end?", ["The boots", "The rain", "A bee"], 0]], "talk": ["What did Jen hop into?", "What color are the boots?"], "coach": ["Warm-up: hop in place on 'hop, hop.'", "Find every word that starts like path: path, puddle."]});
STORIES101.en.push({"id": "d101_en_0_05", "grade": 0, "t": "One More Hug", "text": "The lamp is low. The book is shut.\n\n\"One more hug,\" says Nan.\n\nTed hugs Nan. Nan hugs Ted.\n\nThe bed is soft. The room is calm.\n\nGood night, Ted. Good night, Nan.", "art": "oneHug", "release101": 4, "q": [["What is shut?", ["The book", "The bed", "The hug"], 0], ["How is the bed?", ["Soft", "Loud", "Hot"], 0]], "talk": ["Who asked for one more hug?", "How does the room feel?"], "coach": ["Warm-up: whisper 'good night' and feel how quiet it is.", "Read the hugs slowly. You can hug at that line if you like."]});
STORIES101.en.push({"id": "d101_en_1_01", "grade": 1, "t": "The Porch Bell", "text": "A little bell hangs by the door. When the wind is soft, it does not ring.\n\nOne afternoon, it rang twice. Lila and her dad opened the door.\n\nNo one was there. Then they looked down. A neighbor's cat had bumped the bell with its back.\n\nDad set a small mat under the bell so the cat could pass. The bell kept its song for people who came to visit.", "art": "porchBell", "release101": 0, "q": [["Who bumped the bell?", ["A cat", "A bird", "A truck"], 0], ["What did Dad put under the bell?", ["A small mat", "A drum", "A lamp"], 0], ["What is the bell for?", ["Visitors", "Cooking", "Rain"], 0]], "talk": ["What made the bell ring?", "Why did Dad put a mat there?"], "coach": ["Warm-up: preview porch, neighbor, bumped.", "After the second paragraph, pause and guess together."]});
STORIES101.en.push({"id": "d101_en_1_02", "grade": 1, "t": "A Pocket of Seeds", "text": "Omar found three seeds in the pocket of last year's coat. They were flat and pale.\n\nGrandma said they might still grow. They pressed them into a pot of soil and gave them a little water.\n\nFor many days, the soil looked the same. Omar checked each morning.\n\nOn the eighth day, a green hook pushed up. Omar did not pull it. He waited, and the hook became a leaf.", "art": "pocketSeeds", "release101": 1, "q": [["Where were the seeds?", ["In a coat pocket", "In a shoe", "In a book"], 0], ["What came up on the eighth day?", ["A green hook", "A bird", "A bell"], 0], ["What did Omar do when he saw it?", ["He waited", "He pulled it", "He hid it"], 0]], "talk": ["Where did Omar find the seeds?", "Why didn't he pull the green hook?"], "coach": ["Warm-up: what is a seed? Preview pale, soil, eighth.", "Count to eight on your fingers when you reach that day."]});
STORIES101.en.push({"id": "d101_en_1_03", "grade": 1, "t": "The Quiet Line", "text": "The bakery line was long. Nia stood behind a tall man and could not see the buns.\n\nShe started to squeeze forward. Mom touched her shoulder and they practiced standing still, like trees.\n\nWhen it was their turn, the baker smiled and asked what they would like. Nia could see everything from there.\n\nThey chose two warm rolls and sat on the bench outside. The line behind them moved, one person at a time.", "art": "quietLine", "release101": 2, "q": [["Why was it hard to see?", ["The line was long and a tall man stood in front", "The bakery was closed", "The buns were invisible"], 0], ["What did Mom and Nia practice?", ["Standing still", "Running", "Singing"], 0], ["When could Nia see the buns well?", ["When it was their turn", "Never", "In the rain"], 0]], "talk": ["Why couldn't Nia see at first?", "What did they practice in the line?"], "coach": ["Warm-up: bakery, shoulder, practice.", "Talk about a time you waited, without making it a lecture."]});
STORIES101.en.push({"id": "d101_en_1_04", "grade": 1, "t": "Buttons in a Tin", "text": "A tin of buttons spilled on the rug. Red, blue, two gold, and many that looked almost the same.\n\nJo and Papa sat on the floor. They made little groups: shiny, dull, with two holes, with four.\n\nOne button had no pair. Jo almost put it back alone, then found its match under the chair.\n\nThe tin was full again. Papa said the groups would help next time someone needed just one.", "art": "buttonTin", "release101": 3, "q": [["What spilled?", ["A tin of buttons", "A cup of milk", "A box of sand"], 0], ["Where was the missing button?", ["Under the chair", "In the fridge", "On the roof"], 0], ["Why were the groups useful?", ["They would help next time", "They made the rug louder", "They hid the tin"], 0]], "talk": ["How did they sort the buttons?", "Where was the missing match?"], "coach": ["Warm-up: spilled, groups, match. You can sort real buttons or coins if you have them.", "Praise careful looking, not speed."]});
STORIES101.en.push({"id": "d101_en_1_05", "grade": 1, "t": "The Rain Cape", "text": "The sky turned gray on the walk home from the library. Pia had a book and no hood.\n\nA grown-up at the corner had a wide rain cape. She lifted one side, and Pia walked under it with the book held close.\n\nRain tapped the cape, not the pages. At Pia's steps, they both said thank you — one for the cover, and one for the company.\n\nInside, Pia set the dry book on the table and watched the drops race down the window.", "art": "rainCape", "release101": 4, "q": [["Where were they walking from?", ["The library", "The beach", "A farm"], 0], ["What kept the book dry?", ["A rain cape", "A hat made of paper", "The sun"], 0], ["How was the book at the end?", ["Dry", "Soaked", "Missing"], 0]], "talk": ["How did the book stay dry?", "What did they thank each other for?"], "coach": ["Warm-up: library, cape, company.", "Notice that both people had something to thank."]});
STORIES101.en.push({"id": "d101_en_2_01", "grade": 2, "t": "The Shared Sketchbook", "text": "Maya and her cousin Leo shared one sketchbook on the train. Maya drew a window. Leo added a bird on the sill.\n\nWhen the train went into a tunnel, the page went dark. They waited. In the light again, Leo wanted to draw a second bird, but the first one already felt finished.\n\nMaya turned the page. \"This side is yours,\" she said. Leo drew a tunnel with a small bright end.\n\nThey left the first page as it was. Two pictures, two ideas, and a book that belonged to both of them.", "art": "sharedSketch", "release101": 0, "q": [["What did Maya draw first?", ["A window", "A tunnel", "A train engine"], 0], ["What did Leo add?", ["A bird on the sill", "A river", "A clock"], 0], ["What did Maya do so Leo could try a new idea?", ["She turned the page", "She erased the bird", "She closed the book"], 0]], "talk": ["Why did they wait in the tunnel?", "Why did Maya turn the page?"], "coach": ["Warm-up: sketchbook, cousin, tunnel.", "Ask what it means for a drawing to feel finished."]});
STORIES101.en.push({"id": "d101_en_2_02", "grade": 2, "t": "A Path Around the Puddle", "text": "A wide puddle covered the sidewalk after the storm. Some people stepped into the grass. The grass was already muddy and tired.\n\nRafi and his aunt looked for another way. They used the low stone wall as a quiet edge and walked along it, one careful foot at a time.\n\nA neighbor saw them and brought two boards from a dry porch. Together they made a short, steady path.\n\nThe puddle could stay and shrink on its own. The grass could rest, and no one had to rush through the water.", "art": "puddlePath", "release101": 1, "q": [["Why was the grass a poor path?", ["It was already muddy and tired", "It was on fire", "It was too high"], 0], ["What did a neighbor bring?", ["Two boards", "A boat", "A fan"], 0], ["What could the puddle do then?", ["Shrink on its own", "Follow them home", "Turn into snow"], 0]], "talk": ["Why didn't they walk on the grass?", "How did the boards help?"], "coach": ["Warm-up: sidewalk, muddy, boards.", "Notice the puddle is not treated as a problem to fight, just something to go around."]});
STORIES101.en.push({"id": "d101_en_2_03", "grade": 2, "t": "The Clock That Was Fast", "text": "The classroom clock was five minutes ahead. Every day, the recess bell seemed late, and the children packed up too soon.\n\nMira compared it with the clock in the hall, then with her teacher's watch. All three told slightly different times.\n\nThey asked the office. A staff member came with a small key, reset the classroom clock, and explained that clocks can drift if they are not checked.\n\nThe next day, recess arrived when they expected it. Mira still glanced at the hall clock once, just to be sure.", "art": "fastClock", "release101": 2, "q": [["What was wrong with the classroom clock?", ["It was five minutes ahead", "It was upside down", "It had no numbers"], 0], ["How did Mira check?", ["She compared it with other clocks", "She shook it", "She covered it"], 0], ["What can happen if clocks are not checked?", ["They can drift", "They turn into bells", "They hide"], 0]], "talk": ["How did Mira check the time?", "What does it mean for a clock to drift?"], "coach": ["Warm-up: ahead, compared, drift.", "You can look at two clocks at home and see if they agree."]});
STORIES101.en.push({"id": "d101_en_2_04", "grade": 2, "t": "Moss Letters", "text": "On the shady side of the school wall, moss had grown in patches. From far away, the patches looked like random green clouds.\n\nClose up, Theo noticed that some patches followed the grooves in the brick, like slow letters. He did not pick the moss. He drew what he saw in his notebook.\n\nHis teacher suggested a photograph so the wall could keep its moss. They took one picture and left the rest to grow.\n\nThe next week, Theo compared the drawing and the photograph. The moss had moved only a little, the way a story moves when you read it again.", "art": "mossLetter", "release101": 3, "q": [["Where did the moss grow?", ["On the shady side of a wall", "On the playground slide", "In a lunchbox"], 0], ["What did Theo do instead of picking it?", ["He drew it", "He washed it off", "He hid it"], 0], ["How much had the moss moved the next week?", ["Only a little", "All the way across town", "It was gone"], 0]], "talk": ["Why didn't Theo pick the moss?", "What was useful about the photograph?"], "coach": ["Warm-up: patches, grooves, photograph.", "If you have a wall with moss or cracks, look closely without touching."]});
STORIES101.en.push({"id": "d101_en_2_05", "grade": 2, "t": "The Extra Chair", "text": "The reading circle had just enough chairs. Then a new student arrived with a backpack and a quiet look.\n\nSami got up to fetch a chair from the next room. Two classmates held the circle open so the space would still feel like a circle, not a line.\n\nWhen Sami came back, the new student had a place, and the book was still on the same page.\n\nThey read the next paragraph together. The extra chair stayed in the circle after that, even on days when every seat was not needed.", "art": "extraChair", "release101": 4, "q": [["What did Sami go get?", ["A chair", "A cake", "A bell"], 0], ["What did classmates do while Sami was gone?", ["They held the circle open", "They closed the book forever", "They left"], 0], ["What stayed in the circle after that?", ["The extra chair", "A puddle", "A clock"], 0]], "talk": ["How did the classmates help while Sami was gone?", "Why did they keep the extra chair later?"], "coach": ["Warm-up: circle, fetch, paragraph.", "Talk about what makes a space feel open to someone new."]});
STORIES101.en.push({"id": "d101_en_3_01", "grade": 3, "t": "The Bird Window Census", "text": "Ms. Ortiz's class decided to watch the same courtyard window for one week and write down every bird they could name. The first morning they recorded two sparrows and a hurried shadow they could not identify.\n\nBy Wednesday, they had a system: one person watched, one wrote, and they only counted a bird if at least two classmates agreed. The unidentified shadow returned and sat long enough for them to see a gray back and a pale belly. It was a dove.\n\nOn Friday they made a simple chart. Sparrows came often. The dove came twice. A bright blue bird came once and did not stay.\n\nThey hung the chart beside the window, with a note that it was a beginning, not a complete list. The courtyard, they wrote, was still allowed to surprise them.", "art": "birdWindow", "release101": 0, "q": [["What was the class trying to do?", ["Count and name birds at one window", "Catch birds", "Paint the courtyard"], 0], ["How did they finally name the shadow?", ["It sat long enough to see its colors", "They guessed from a song", "They chased it"], 0], ["What did they write beside the chart?", ["That it was a beginning, not a complete list", "That no more birds would come", "That the window should stay shut"], 0]], "talk": ["Why did they need two classmates to agree?", "What did the note on the chart say?"], "coach": ["Warm-up: census, identify, courtyard.", "Ask how waiting helped them name the shadow."]});
STORIES101.en.push({"id": "d101_en_3_02", "grade": 3, "t": "A Recipe in Two Hands", "text": "Abuela's bread recipe was written on a card so worn that a few words had faded. \"Warm water,\" it still said, and \"a pinch of salt,\" but the rest of the flour amount was a pale smudge.\n\nElena held the bowl. Abuela held the card to the light and remembered out loud: enough flour so the dough pulled away from the sides, not so much that it felt dry.\n\nThey added flour a little at a time and took turns touching the dough. When it felt right to both of them, they stopped.\n\nLater, Elena copied a new card. She wrote the old words, then a new line: \"Add flour until it feels ready, and ask someone to feel it too.\" The smell in the kitchen was the same as always.", "art": "twoHands", "release101": 1, "q": [["What had happened to the recipe card?", ["Some words had faded", "It had been baked", "It was written in a secret code"], 0], ["How did they know when to stop adding flour?", ["The dough felt right to both of them", "They used a clock", "They guessed once and left"], 0], ["What did Elena add to the new card?", ["A line about feeling the dough together", "A drawing of a bus", "A list of birds"], 0]], "talk": ["Why couldn't they just follow the numbers?", "What new line did Elena write?"], "coach": ["Warm-up: recipe, faded, smudge, dough.", "If you bake or mix something, notice how 'enough' can be a feeling as well as a number."]});
STORIES101.en.push({"id": "d101_en_3_03", "grade": 3, "t": "The Forgotten Library Card", "text": "Jonah reached the front desk with a stack of books and an empty pocket. His library card was at home, still on the hook by the door.\n\nThe librarian did not scold him. She set the books aside and showed him how a hold worked: the books would wait under his name for a few days, and no one else would take them in the meantime.\n\nJonah walked home with no stack in his arms and a slip of paper in his hand. He found the card exactly where he had left it.\n\nThe next afternoon he came back, showed the card, and the same books were waiting. He started a small habit of checking his pocket on the steps, before he went in.", "art": "libraryCard", "release101": 2, "q": [["What had Jonah forgotten?", ["His library card", "The librarian's name", "How to read"], 0], ["What is a hold, in this story?", ["Books wait under your name for a few days", "The library closes", "You must buy the books"], 0], ["What did Jonah begin to do?", ["Check his pocket on the steps", "Leave the card at school", "Stop visiting"], 0]], "talk": ["What did the librarian do instead of sending him away empty?", "What new habit did Jonah start?"], "coach": ["Warm-up: desk, hold, habit.", "Talk about a time a plan had to change, and what still worked."]});
STORIES101.en.push({"id": "d101_en_3_04", "grade": 3, "t": "The Warm Side of the Stone", "text": "On a cool morning walk, Imani and her uncle sat on a low wall. One side of a big stone was cool and gray. The side that faced the sun was faintly warm.\n\nImani turned the idea over. The stone had not made its own heat. It had kept some of the sunlight from earlier, the way a thick mug keeps tea warm after the kettle is off.\n\nThey felt a smaller stone nearby. It was already closer to the air's temperature. Uncle said thinner things change faster, and thicker things take longer to warm or cool.\n\nOn the way home, Imani touched the dark garden soil and the pale path. She was not trying to pick a favorite. She was practicing noticing.", "art": "warmStone", "release101": 3, "q": [["Where did the stone's warmth come from?", ["Sunlight it had kept", "A fire inside it", "The moon"], 0], ["How did the smaller stone feel?", ["Closer to the air's temperature", "Boiling", "Frozen solid"], 0], ["What was Imani practicing?", ["Noticing", "Skipping stones at people", "Naming every insect"], 0]], "talk": ["Why was one side of the stone warm?", "Why did the smaller stone feel different?"], "coach": ["Warm-up: faintly, temperature, soil.", "You can feel a sunny windowsill and a shady one and compare, gently."]});
STORIES101.en.push({"id": "d101_en_3_05", "grade": 3, "t": "The Night Bus Stop", "text": "The last bus was due in ten minutes. Noor stood with her dad under the shelter. A few drops clicked on the roof, then stopped. The street was quiet enough that they could hear a radio in a far kitchen.\n\nA neighbor arrived and asked if this was the right stop for the lake road. Dad said yes, and they made a little more room on the bench.\n\nWhen the bus came, its lights were warm and low, not sharp. The three of them got on. Noor pressed the bell a stop early by accident, then told the driver, who smiled and said the next stop was fine.\n\nAt home, Noor wrote one line in her notebook: the night felt large, and the people in it had been kind in small ways.", "art": "nightStop", "release101": 4, "q": [["Who waited with Noor?", ["Her dad", "No one", "A stranger she did not know"], 0], ["What did they do for the neighbor?", ["Said it was the right stop and made room", "Told the neighbor to leave", "Hid from the bus"], 0], ["What did the driver do when Noor pressed the bell early?", ["Said the next stop was fine", "Drove away without them", "Turned off the lights"], 0]], "talk": ["How did they help the neighbor?", "What did Noor want to remember?"], "coach": ["Warm-up: shelter, due, accident. The family is together the whole time.", "Notice the small kindnesses: room on the bench, a patient driver."]});
STORIES101.en.push({"id": "d101_en_4_01", "grade": 4, "t": "The Map of Fallen Stars", "text": "After a clear August night, a few classmates arrived at school talking about streaks of light. Some called them falling stars. Their science teacher spread a simple sky map on the table and said the streaks were meteors: small bits of rock from space heating up as they passed through Earth's air.\n\nNo one in the class had seen the same part of the sky. They marked their approximate directions on a shared paper — over the water tower, above the west hills, near the bright planet that had been out early.\n\nThe marks did not make one line. They made a loose spray, which fit what the teacher had said: meteors in a shower can seem to come from one region of the sky, but each path is its own.\n\nThey left the map on the wall for a week, with a careful credit to the idea, not to a single observer. The next clear night, two students went out with their families and watched without trying to finish the map. Looking, they decided, was already a kind of keeping.", "art": "fallenStars", "release101": 0, "q": [["What were the streaks of light?", ["Meteors heating up in the air", "Stars falling out of the sky for good", "Airplane landing lights only"], 0], ["Why were the classmates' marks in different places?", ["They had looked at different parts of the sky", "The map was torn", "They were drawing invented paths"], 0], ["What did two students do on the next clear night?", ["Watched with their families without trying to finish the map", "Tried to collect meteors in jars", "Turned all the streetlights off"], 0]], "talk": ["What are 'falling stars' in this story?", "Why didn't the marks make a single line?"], "coach": ["Warm-up: meteors, approximate, region, observer.", "If you go out at night, look together and keep it calm — no need to catch every streak."]});
STORIES101.en.push({"id": "d101_en_4_02", "grade": 4, "t": "A Letter in Two Languages", "text": "Sofia's abuelo wrote her a letter in Spanish, in a steady hand. Sofia's everyday school language was English, and some sentences asked her to slow down.\n\nShe did not rush to a perfect translation. She read each line twice, once for the sound and once for the meaning, and she made a narrow column of words she wanted to ask about. A few were easy: cielo, mesa, domingo. One phrase, con calma, she already used at home.\n\nOn Sunday she called him. They went through the column together, and he told her why he had chosen one word instead of another. Then she wrote back, first in English, then she tried three sentences in Spanish, leaving a little space under each.\n\nHe answered those sentences without correcting every letter. He answered the ideas. Sofia kept both letters in the same envelope, because they belonged together.", "art": "twoLanguages", "release101": 1, "q": [["What did Sofia do instead of rushing a perfect translation?", ["She read twice and made a column of questions", "She threw the letter away", "She asked a stranger to rewrite it"], 0], ["What did they do on Sunday?", ["They went through the words together on a call", "They forgot the letter", "They translated a whole book"], 0], ["How did he answer her Spanish sentences?", ["He answered the ideas, without correcting every letter", "He refused to read them", "He gave her a grade"], 0]], "talk": ["How did Sofia read the letter?", "What did her abuelo answer — the spelling, or the ideas?"], "coach": ["Warm-up: translation, phrase, column.", "If your family uses two languages, notice how meaning can travel even when a sentence is still learning its shape."]});
STORIES101.en.push({"id": "d101_en_4_03", "grade": 4, "t": "The Garden's Quiet Helpers", "text": "The community garden's tomatoes looked tired, even though people watered them often. A volunteer named Priya invited a few kids to look at the soil, not just the leaves.\n\nUnder a lifted handful, they found damp darkness, a pale root, and two earthworms moving slowly away from the light. Priya said worms and other small lives help air and leftover leaves mix into the soil, which helps plants drink and stand.\n\nThe group decided to add a layer of dry leaves around the plants, leaving space around each stem, and to step on the paths instead of the beds. They also agreed not to collect the worms.\n\nTwo weeks later the soil felt looser under a careful finger. The tomatoes were not magic-tall, but they looked less tired. Priya wrote a small sign: \"Helpers you may not see are still at work. Please walk on the path.\"", "art": "quietHelpers", "release101": 2, "q": [["What did Priya ask them to look at?", ["The soil, not just the leaves", "Only the garden fence", "The clouds"], 0], ["How do worms help, in this story?", ["They help mix air and leftover leaves into the soil", "They water the plants at night with tiny cans", "They scare the tomatoes into growing"], 0], ["What did the group agree to do?", ["Add leaves, stay on the paths, and leave the worms", "Take the worms home", "Pull up the tomatoes"], 0]], "talk": ["What did they look at besides the leaves?", "Why didn't they collect the worms?"], "coach": ["Warm-up: soil, earthworms, beds (garden beds), looser.", "If you visit a garden, stay on paths and look without taking the living things home."]});
STORIES101.en.push({"id": "d101_en_4_04", "grade": 4, "t": "The Frozen Birdbath", "text": "After a sharp night, the water in the backyard birdbath had turned to a smooth lid of ice. In the morning, two sparrows landed on the rim, hopped, and left.\n\nNadia's dad did not pour boiling water on the ice. He brought a shallow dish of cool water and set it beside the bath, in a calm, open spot the cats could not easily hide near. Then they lifted the frozen bowl inside to thaw slowly in the sink.\n\nNadia asked why the new dish was shallow. Dad said birds need to stand and leave easily, and deep water is harder for them.\n\nBy afternoon the original bath was liquid again. They refilled it and brought the extra dish in, so they would not leave a pool overnight to freeze as a trap. The sparrows came back near dusk and drank, then went to the hedge.", "art": "birdBath", "release101": 3, "q": [["What had happened to the birdbath?", ["The water had frozen", "It had flown away", "It was full of snowmen"], 0], ["What did they offer the birds instead of boiling the ice?", ["A shallow dish of cool water nearby", "Nothing until summer", "A closed bottle"], 0], ["Why did they bring the extra dish in later?", ["So it would not freeze overnight in a way that could trap", "To hide it from the sparrows", "Because dishes cannot get wet"], 0]], "talk": ["Why didn't they use boiling water?", "Why was the dish shallow, and why didn't it stay out overnight?"], "coach": ["Warm-up: birdbath, thaw, shallow, hedge.", "Kindness to animals here is practical and calm — no chasing or catching."]});
STORIES101.en.push({"id": "d101_en_4_05", "grade": 4, "t": "The Story They Told Twice", "text": "For a class project, Amir and Lina had to tell a family story two ways: once as it was first told to them, and once with only the parts they could support.\n\nThe first telling was full of color. A great-uncle had walked across a long bridge in a storm, and the wind had \"almost carried him into the river.\" It was a good sentence to hear.\n\nFor the second telling, they asked Amir's mother what she remembered being told, and what she had seen herself. She had seen the great-uncle come home wet, laughing, and tired. She had not seen the bridge. The storm, she said, was real; the \"almost\" was the shape a story takes when it is passed along.\n\nThey presented both versions, side by side, without calling one a lie. The class talked about how a story can keep a feeling and still leave room for what no one present can prove. Amir wrote that both tellings belonged in the family, for different reasons.", "art": "toldTwice", "release101": 4, "q": [["What were Amir and Lina asked to do?", ["Tell a family story two ways", "Invent a storm", "Build a bridge"], 0], ["What had Amir's mother seen herself?", ["Her great-uncle come home wet, laughing, and tired", "The wind lifting him off the bridge", "Nothing at all"], 0], ["How did they present the two versions?", ["Side by side, without calling one a lie", "They threw the first one away", "They pretended they were the same"], 0]], "talk": ["What was different about the second telling?", "Why didn't they call the first telling a lie?"], "coach": ["Warm-up: support (as in evidence), version, prove.", "This is a gentle lesson about memory and evidence, not about catching someone out."]});
STORIES101.en.push({"id": "d101_en_5_01", "grade": 5, "t": "The Light That Reached the Well", "text": "The town museum kept a dry, covered well in its courtyard as part of an old house. A sign said visitors should not throw coins. Still, the bottom looked only like darkness.\n\nA fifth-grade group was studying how light travels. Their teacher brought a small mirror and a flashlight, and, with permission, they angled the beam off the mirror until a pale circle appeared on the brick at the bottom. Dust made the path of the light faintly visible in the air.\n\nThey measured, roughly, how the angle they chose changed where the circle landed. Someone said it felt like cheating, using a tool to see what the eyes could not. Another student said it felt like asking a better question.\n\nThey turned the flashlight off and let the well be dark again. In their notes they wrote that darkness at the bottom had not meant emptiness. It had meant the light they arrived with was not yet in the right place.", "art": "wellLight", "release101": 0, "q": [["What appeared when they angled the light?", ["A pale circle on the brick at the bottom", "A coin they were told to throw", "A second sun"], 0], ["What made the path of the light faintly visible?", ["Dust in the air", "Paint", "A radio"], 0], ["What did they write about the darkness?", ["It had not meant emptiness", "That the well should be filled with soil", "That light can never go down"], 0]], "talk": ["What did the mirror and flashlight show?", "What did their notes say about the darkness?"], "coach": ["Warm-up: courtyard, angle, visible, emptiness.", "A gentle science moment: tools help us look, and then we leave the place as we found it."]});
STORIES101.en.push({"id": "d101_en_5_02", "grade": 5, "t": "What the River Kept", "text": "On a Saturday cleanup, a science club walked a short stretch of riverbank with gloves and bags. They had been asked to take trash and to leave living plants and loose natural stones.\n\nNear a bend, Marisol found a smooth, heavy shape half in the mud. It looked at first like a dark, oval rock. When she rinsed it in a bucket, a spiral pattern showed, raised and regular. Their mentor said it might be a fossil — a print or remain of something that lived long ago — but that a careful identification belonged at the nature center, not in a backpack.\n\nThey photographed it where it lay, marked the spot on a simple sketch, and, with the mentor, carried it only as far as the center's front desk, along with the day's trash bags.\n\nA week later a note came back: it was a fossil shell, common in that valley's older rock, and it would stay in a drawer students could visit. Marisol liked that the river had kept it a long time, and that their job had been to notice, not to own.", "art": "riverKept", "release101": 1, "q": [["What were they supposed to take from the bank?", ["Trash, not living plants or loose natural stones", "All the stones they liked", "Fish"], 0], ["What made them think the shape might be a fossil?", ["A raised, regular spiral after rinsing", "It glowed in the dark", "It made a sound"], 0], ["Where did the fossil end up?", ["In a drawer at the nature center that students could visit", "In Marisol's backpack for good", "Thrown back without a record"], 0]], "talk": ["Why didn't they drop the find into a backpack right away?", "What happened to the fossil?"], "coach": ["Warm-up: riverbank, fossil, identification, mentor.", "Collecting from nature is handled carefully here: notice, ask, and let a proper place keep it."]});
STORIES101.en.push({"id": "d101_en_5_03", "grade": 5, "t": "The Day the Class Measured Silence", "text": "The music room had a problem that was not a broken instrument. After lunch, the hallway roar leaked under the door, and quiet pieces were hard to hear.\n\nInstead of just complaining, the class tried a measurement. They chose three times of day and, with a simple meter their teacher already owned, recorded how loud the hallway was just outside and just inside the room. They also noted whether the door was fully shut.\n\nThe numbers were not perfect, but the pattern was clear. Mid-afternoon was loudest. A fully shut door helped a little. A folded blanket along the bottom of the door, which the custodian approved, helped more.\n\nThey wrote a short report for the principal, with their chart and a thank-you to the custodian. The hallway was still a hallway. The room, though, could hold a soft piece again, and the class had a method they could use on other noisy questions.", "art": "measureSilence", "release101": 2, "q": [["What problem did the music room have?", ["Hallway noise leaked in and made quiet pieces hard to hear", "All the instruments were missing", "The teacher canceled music"], 0], ["What did they do besides complain?", ["They measured loudness at three times of day", "They shouted back", "They moved the school"], 0], ["What helped more than just shutting the door?", ["A folded blanket along the bottom, with approval", "Removing the door", "Turning the hallway into a stage"], 0]], "talk": ["What did they measure, and when?", "What actually helped the room?"], "coach": ["Warm-up: leaked, meter, pattern, custodian.", "This is problem-solving with evidence, not a campaign against anyone."]});
STORIES101.en.push({"id": "d101_en_5_04", "grade": 5, "t": "An Orbit We Could Draw", "text": "In Look Up, the class had already lined the planets in their real order from the Sun. Now their teacher asked a harder, quieter question: if Earth is one, how could they show Jupiter's size without squeezing the whole Solar System onto one page?\n\nThey tried two drawings. The first put all eight planets in a row, sized to fit the paper. Jupiter looked only a little bigger than Earth, which felt wrong once they read a NASA comparison: if Jupiter were a hollow shell, about one thousand Earths could fit inside it. If Earth were the size of a grape, Jupiter would be about as big as a basketball.\n\nThe second drawing showed only Earth and Jupiter, with Earth as a small circle and Jupiter as a circle that nearly reached the edge of a poster. The other planets were named in a list at the side, with a note that distance is a different kind of hugeness and needed a different drawing.\n\nThey hung both posters and wrote, under the second, where the comparison came from. A few students said the first poster was still useful for order. The second, they said, was for respect — for not making a giant look ordinary just because the paper was small.", "art": "orbitDraw", "release101": 3, "q": [["What comparison did they read about Jupiter?", ["About 1,000 Earths could fit inside it", "It is smaller than the Moon", "It is the closest planet to the Sun"], 0], ["What did the second drawing show?", ["Only Earth and Jupiter, closer to a fair size difference", "All eight planets at true distance", "A map of their town"], 0], ["Why keep the first poster too?", ["It was still useful for showing order", "It had better colors", "The teacher required two mistakes"], 0]], "talk": ["Why did the first drawing feel wrong?", "What two kinds of hugeness did they separate?"], "coach": ["Warm-up: orbit, comparison, distance, scale. The number comes from NASA and is framed as a comparison, not a raw figure to memorize.", "You can look at Look Up in the app after reading, and talk about size versus order."]});
STORIES101.en.push({"id": "d101_en_5_05", "grade": 5, "t": "The Bench With Two Plaques", "text": "A park bench had two small plaques, one at each end, with two different names and two years that were twenty years apart. Kenji sat with his aunt and read both, then looked at the trees as if they might explain.\n\nA park volunteer, sweeping the path, saw them reading and offered what the file at the toolshed said. The first plaque was from a family who had liked this view of the pond. Years later, when the bench slats were replaced, a second family asked to add a second plaque rather than take the first one off.\n\nThe volunteer said the park's rule was simple: a repair should not erase a memory if there is room for both. Kenji ran his hand along the new slats and the older metal arm.\n\nHe told his aunt he had thought one name would have to win. He liked the other idea better — that a place can hold two thank-yous, and that a repair can stay visible without pretending the bench had always been new.", "art": "twoPlaques", "release101": 4, "q": [["What did Kenji notice on the bench?", ["Two plaques with different names and years", "A hidden map", "A broken swing tied to it"], 0], ["Why was the second plaque added?", ["A second family asked to add one when the slats were replaced, instead of taking the first off", "The first plaque had been a mistake", "The volunteer needed more metal"], 0], ["What rule did the volunteer describe?", ["A repair should not erase a memory if there is room for both", "Only one name is allowed in a park", "Old benches must be hidden"], 0]], "talk": ["Why are there two plaques?", "What was the park's rule about repair and memory?"], "coach": ["Warm-up: plaques, slats, erase, visible.", "A calm story about sharing remembrance, without dwelling on loss. Keep the talk gentle."]});
// Spanish (original, not literal)
STORIES101.es.push({"id": "d101_es_0_01", "grade": 0, "t": "El gorro suave", "text": "Mia tiene un gorro. El gorro es suave.\n\nEl viento es fuerte. El gorro puede volar.\n\nPapá sujeta el gorro. Mia también lo sujeta.\n\nEl gorro se queda. El viento puede jugar.", "art": "softHat", "release101": 0, "q": [["¿Qué es suave?", ["El gorro", "El viento", "Una piedra"], 0], ["¿Quién sujeta el gorro con Mia?", ["Papá", "Un pato", "Un bicho"], 0]], "talk": ["¿Quién ayudó a Mia a guardar el gorro?", "¿Qué le gusta hacer al viento?"], "coach": ["Antes de leer, digan despacio: gorro, viento, suave.", "Lean las dos últimas líneas con voz calmada."]});
STORIES101.es.push({"id": "d101_es_0_02", "grade": 0, "t": "Mermelada en la sartén", "text": "La sartén está tibia. Mamá pone mermelada.\n\nSam ve la mermelada. Es roja y lenta.\n\nMamá la pone en un pan.\n\nSam prueba un bocado. Mamá también.\n\nMermelada dulce. Un buen comienzo.", "art": "jamPan", "release101": 1, "q": [["¿De qué color es la mermelada?", ["Roja", "Azul", "Negra"], 0], ["¿Dónde ponen la mermelada?", ["En un pan", "En un gorro", "En un zapato"], 0]], "talk": ["¿Qué pusieron en el pan?", "¿Quién probó un bocado?"], "coach": ["Antes de leer, den palmas con: mermelada, sartén, pan.", "En «mermelada dulce», hagan como si oliéramos el desayuno."]});
STORIES101.es.push({"id": "d101_es_0_03", "grade": 0, "t": "Un bicho en el capullo", "text": "Hay un capullo en un tallo. Es pequeño.\n\nUn bicho se sienta en el capullo.\n\nEl bicho está quieto. El capullo también.\n\nPasa una abeja. El bicho no salta.\n\nEl sol es tibio. Ellos descansan.", "art": "bugBud", "release101": 2, "q": [["¿Dónde se sienta el bicho?", ["En un capullo", "En una taza", "En un gorro"], 0], ["¿Cómo es el sol?", ["Tibio", "Frío", "Mojado"], 0]], "talk": ["¿Quién se sentó en el capullo?", "¿Qué hizo el bicho cuando pasó la abeja?"], "coach": ["Estiren: bicho, capullo, abeja.", "En «quieto», quédense un momento sin moverse."]});
STORIES101.es.push({"id": "d101_es_0_04", "grade": 0, "t": "El camino mojado", "text": "Había lluvia en el camino. Chis, chis, chis.\n\nJen tiene botas rojas.\n\nJen salta a un charco. Salta, salta.\n\nJen salta al siguiente. El camino es divertido.\n\nAl final, Jen llega a casa. Las botas pueden descansar.", "art": "wetPath", "release101": 3, "q": [["¿Qué hay en el camino?", ["Lluvia", "Nieve", "Arena"], 0], ["¿Qué puede descansar al final?", ["Las botas", "La lluvia", "Una abeja"], 0]], "talk": ["¿A qué saltó Jen?", "¿De qué color son las botas?"], "coach": ["En «salta, salta», den un saltito en el sitio.", "Busquen palabras que empiezan como camino."]});
STORIES101.es.push({"id": "d101_es_0_05", "grade": 0, "t": "Un abrazo más", "text": "La lámpara está baja. El libro está cerrado.\n\n«Un abrazo más», dice Nana.\n\nTed abraza a Nana. Nana abraza a Ted.\n\nLa cama es suave. El cuarto está en calma.\n\nBuenas noches, Ted. Buenas noches, Nana.", "art": "oneHug", "release101": 4, "q": [["¿Qué está cerrado?", ["El libro", "La cama", "El abrazo"], 0], ["¿Cómo es la cama?", ["Suave", "Ruidosa", "Caliente"], 0]], "talk": ["¿Quién pidió un abrazo más?", "¿Cómo se siente el cuarto?"], "coach": ["Susurren «buenas noches» y noten el silencio.", "Pueden darse un abrazo al leer esa línea."]});
STORIES101.es.push({"id": "d101_es_1_01", "grade": 1, "t": "La campana del porche", "text": "Una campanita cuelga junto a la puerta. Si el viento es suave, no suena.\n\nUna tarde, sonó dos veces. Lila y su papá abrieron la puerta.\n\nNo había nadie. Luego miraron hacia abajo. El gato del vecino había tocado la campana con el lomo.\n\nPapá puso un felpudo pequeño bajo la campana para que el gato pasara. La campana guardó su canción para quienes llegan de visita.", "art": "porchBell", "release101": 0, "q": [["¿Quién tocó la campana?", ["Un gato", "Un pájaro", "Un camión"], 0], ["¿Qué puso papá bajo la campana?", ["Un felpudo pequeño", "Un tambor", "Una lámpara"], 0], ["¿Para qué es la campana?", ["Para las visitas", "Para cocinar", "Para la lluvia"], 0]], "talk": ["¿Qué hizo sonar la campana?", "¿Por qué papá puso un felpudo?"], "coach": ["Antes de leer, comenten: porche, vecino, lomo.", "Después del segundo párrafo, adivinen juntos."]});
STORIES101.es.push({"id": "d101_es_1_02", "grade": 1, "t": "Un bolsillo de semillas", "text": "Omar encontró tres semillas en el bolsillo del abrigo del año pasado. Eran planas y pálidas.\n\nLa abuela dijo que aún podían crecer. Las pusieron en una maceta con tierra y les dieron un poco de agua.\n\nDurante muchos días, la tierra se veía igual. Omar miraba cada mañana.\n\nAl octavo día, surgió un gancho verde. Omar no lo jaló. Esperó, y el gancho se volvió una hoja.", "art": "pocketSeeds", "release101": 1, "q": [["¿Dónde estaban las semillas?", ["En un bolsillo del abrigo", "En un zapato", "En un libro"], 0], ["¿Qué salió al octavo día?", ["Un gancho verde", "Un pájaro", "Una campana"], 0], ["¿Qué hizo Omar al verlo?", ["Esperó", "Lo jaló", "Lo escondió"], 0]], "talk": ["¿Dónde encontró Omar las semillas?", "¿Por qué no jaló el gancho verde?"], "coach": ["Comenten qué es una semilla. Palabras: pálidas, tierra, octavo.", "Al llegar al octavo día, cuenten hasta ocho con los dedos."]});
STORIES101.es.push({"id": "d101_es_1_03", "grade": 1, "t": "La fila tranquila", "text": "La fila de la panadería era larga. Nia estaba detrás de un hombre alto y no veía los panes.\n\nQuiso adelantarse. Mamá le tocó el hombro y practicaron quedarse quietas, como árboles.\n\nCuando les tocó el turno, el panadero sonrió y preguntó qué querían. Desde allí Nia lo veía todo.\n\nEligieron dos panes calientes y se sentaron en el banco de afuera. La fila de atrás avanzaba, una persona a la vez.", "art": "quietLine", "release101": 2, "q": [["¿Por qué era difícil ver?", ["La fila era larga y un hombre alto estaba delante", "La panadería estaba cerrada", "Los panes eran invisibles"], 0], ["¿Qué practicaron mamá y Nia?", ["Quedarse quietas", "Correr", "Cantar"], 0], ["¿Cuándo pudo Nia ver bien los panes?", ["Cuando les tocó el turno", "Nunca", "Bajo la lluvia"], 0]], "talk": ["¿Por qué Nia no podía ver al principio?", "¿Qué practicaron en la fila?"], "coach": ["Palabras: panadería, hombro, practicar.", "Recuerden una vez que esperaron, sin convertirlo en un sermón."]});
STORIES101.es.push({"id": "d101_es_1_04", "grade": 1, "t": "Botones en una lata", "text": "Una lata de botones se cayó en la alfombra. Rojos, azules, dos dorados y muchos que se parecían.\n\nJo y papá se sentaron en el suelo. Hicieron grupitos: brillantes, opacos, de dos agujeros, de cuatro.\n\nUn botón no tenía pareja. Jo estuvo a punto de dejarlo solo, y entonces encontró su pareja debajo de la silla.\n\nLa lata se llenó otra vez. Papá dijo que los grupos ayudarían cuando alguien necesitara solo uno.", "art": "buttonTin", "release101": 3, "q": [["¿Qué se cayó?", ["Una lata de botones", "Una taza de leche", "Una caja de arena"], 0], ["¿Dónde estaba el botón que faltaba?", ["Debajo de la silla", "En la nevera", "En el techo"], 0], ["¿Para qué servían los grupos?", ["Ayudarían la próxima vez", "Hacían más ruidosa la alfombra", "Escondían la lata"], 0]], "talk": ["¿Cómo ordenaron los botones?", "¿Dónde estaba la pareja que faltaba?"], "coach": ["Palabras: lata, grupos, pareja. Si tienen botones de verdad, pueden clasificarlos.", "Valoren la mirada atenta, no la prisa."]});
STORIES101.es.push({"id": "d101_es_1_05", "grade": 1, "t": "La capa de lluvia", "text": "El cielo se puso gris en el camino de vuelta de la biblioteca. Pia llevaba un libro y no tenía capucha.\n\nEn la esquina, una persona adulta tenía una capa de lluvia ancha. Levantó un lado, y Pia caminó debajo con el libro cerca.\n\nLa lluvia golpeaba la capa, no las páginas. En los escalones de Pia, las dos dieron las gracias: una por el abrigo, y la otra por la compañía.\n\nDentro, Pia dejó el libro seco en la mesa y miró las gotas correr por la ventana.", "art": "rainCape", "release101": 4, "q": [["¿De dónde volvían?", ["De la biblioteca", "De la playa", "De una granja"], 0], ["¿Qué mantuvo seco el libro?", ["Una capa de lluvia", "Un sombrero de papel", "El sol"], 0], ["¿Cómo estaba el libro al final?", ["Seco", "Empapado", "Perdido"], 0]], "talk": ["¿Cómo se mantuvo seco el libro?", "¿Por qué se dieron las gracias?"], "coach": ["Palabras: biblioteca, capa, compañía.", "Noten que las dos tenían algo que agradecer."]});
STORIES101.es.push({"id": "d101_es_2_01", "grade": 2, "t": "El cuaderno compartido", "text": "Maya y su primo Leo compartían un solo cuaderno de dibujo en el tren. Maya dibujó una ventana. Leo añadió un pájaro en el alféizar.\n\nCuando el tren entró en un túnel, la página se oscureció. Esperaron. Al volver la luz, Leo quiso dibujar un segundo pájaro, pero el primero ya se sentía terminado.\n\nMaya pasó la hoja. «Este lado es tuyo», dijo. Leo dibujó un túnel con un extremo claro y pequeño.\n\nDejaron la primera página como estaba. Dos dibujos, dos ideas y un cuaderno que era de los dos.", "art": "sharedSketch", "release101": 0, "q": [["¿Qué dibujó Maya primero?", ["Una ventana", "Un túnel", "Una locomotora"], 0], ["¿Qué añadió Leo?", ["Un pájaro en el alféizar", "Un río", "Un reloj"], 0], ["¿Qué hizo Maya para que Leo probara una idea nueva?", ["Pasó la hoja", "Borró el pájaro", "Cerró el cuaderno"], 0]], "talk": ["¿Por qué esperaron en el túnel?", "¿Por qué Maya pasó la hoja?"], "coach": ["Palabras: cuaderno, primo, túnel.", "Comenten qué significa que un dibujo se sienta terminado."]});
STORIES101.es.push({"id": "d101_es_2_02", "grade": 2, "t": "Un camino alrededor del charco", "text": "Después de la tormenta, un charco ancho cubría la acera. Algunas personas pisaban el césped. El césped ya estaba embarrado y cansado.\n\nRafi y su tía buscaron otro modo. Usaron el muro bajo de piedra como borde y caminaron por él, un pie cuidadoso a la vez.\n\nUn vecino los vio y trajo dos tablas de un porche seco. Juntos hicieron un camino corto y firme.\n\nEl charco podía quedarse y menguar solo. El césped podía descansar, y nadie tenía que cruzar el agua de prisa.", "art": "puddlePath", "release101": 1, "q": [["¿Por qué el césped no era un buen camino?", ["Ya estaba embarrado y cansado", "Estaba en llamas", "Era demasiado alto"], 0], ["¿Qué trajo un vecino?", ["Dos tablas", "Un barco", "Un ventilador"], 0], ["¿Qué podía hacer entonces el charco?", ["Menguar solo", "Seguirlos a casa", "Volverse nieve"], 0]], "talk": ["¿Por qué no caminaron por el césped?", "¿Cómo ayudaron las tablas?"], "coach": ["Palabras: acera, embarrado, tablas.", "Noten que el charco no es un enemigo: solo hay que rodearlo."]});
STORIES101.es.push({"id": "d101_es_2_03", "grade": 2, "t": "El reloj que adelantaba", "text": "El reloj del aula adelantaba cinco minutos. Cada día, la campana del recreo parecía tardar, y los niños recogían demasiado pronto.\n\nMira lo comparó con el reloj del pasillo y luego con el reloj de la maestra. Los tres marcaban horas un poco distintas.\n\nPreguntaron en la oficina. Alguien vino con una llavecita, puso bien el reloj del aula y explicó que los relojes pueden desviarse si no se revisan.\n\nAl día siguiente, el recreo llegó cuando lo esperaban. Mira aún miró una vez el reloj del pasillo, solo para estar segura.", "art": "fastClock", "release101": 2, "q": [["¿Qué le pasaba al reloj del aula?", ["Adelantaba cinco minutos", "Estaba al revés", "No tenía números"], 0], ["¿Cómo lo comprobó Mira?", ["Lo comparó con otros relojes", "Lo agitó", "Lo tapó"], 0], ["¿Qué puede pasar si no se revisan los relojes?", ["Pueden desviarse", "Se vuelven campanas", "Se esconden"], 0]], "talk": ["¿Cómo comprobó Mira la hora?", "¿Qué significa que un reloj se desvíe?"], "coach": ["Palabras: adelantar, comparar, desviarse.", "Pueden mirar dos relojes en casa y ver si coinciden."]});
STORIES101.es.push({"id": "d101_es_2_04", "grade": 2, "t": "Letras de musgo", "text": "En el lado de sombra del muro de la escuela, el musgo había crecido en manchas. De lejos, las manchas parecían nubes verdes sin orden.\n\nDe cerca, Theo vio que algunas seguían las ranuras del ladrillo, como letras lentas. No arrancó el musgo. Dibujó lo que veía en su cuaderno.\n\nSu maestra sugirió una fotografía para que el muro conservara el musgo. Tomaron una foto y dejaron que el resto creciera.\n\nA la semana siguiente, Theo comparó el dibujo y la foto. El musgo se había movido solo un poco, como se mueve un cuento cuando lo vuelves a leer.", "art": "mossLetter", "release101": 3, "q": [["¿Dónde crecía el musgo?", ["En el lado de sombra de un muro", "En el tobogán", "En una fiambrera"], 0], ["¿Qué hizo Theo en vez de arrancarlo?", ["Lo dibujó", "Lo lavó", "Lo escondió"], 0], ["¿Cuánto se había movido el musgo a la semana siguiente?", ["Solo un poco", "Hasta el otro lado del pueblo", "Había desaparecido"], 0]], "talk": ["¿Por qué Theo no arrancó el musgo?", "¿Para qué sirvió la fotografía?"], "coach": ["Palabras: manchas, ranuras, fotografía.", "Si hay un muro con musgo o grietas, mírenlo de cerca sin tocarlo."]});
STORIES101.es.push({"id": "d101_es_2_05", "grade": 2, "t": "La silla de más", "text": "En el círculo de lectura había sillas justas. Entonces llegó un estudiante nuevo, con mochila y una mirada tranquila.\n\nSami se levantó a buscar una silla en el cuarto de al lado. Dos compañeros mantuvieron el círculo abierto para que el espacio siguiera siendo un círculo, no una fila.\n\nCuando Sami volvió, el estudiante nuevo tenía un lugar, y el libro seguía en la misma página.\n\nLeyeron juntos el párrafo siguiente. La silla de más se quedó en el círculo desde entonces, también en los días en que no se necesitaba cada asiento.", "art": "extraChair", "release101": 4, "q": [["¿Qué fue a buscar Sami?", ["Una silla", "Un pastel", "Una campana"], 0], ["¿Qué hicieron los compañeros mientras Sami no estaba?", ["Mantuvieron el círculo abierto", "Cerraron el libro para siempre", "Se fueron"], 0], ["¿Qué se quedó en el círculo después?", ["La silla de más", "Un charco", "Un reloj"], 0]], "talk": ["¿Cómo ayudaron los compañeros mientras Sami no estaba?", "¿Por qué dejaron después la silla de más?"], "coach": ["Palabras: círculo, buscar, párrafo.", "Hablen de lo que hace que un espacio se sienta abierto para alguien nuevo."]});
STORIES101.es.push({"id": "d101_es_3_01", "grade": 3, "t": "El censo de la ventana", "text": "La clase de la señora Ortiz decidió mirar la misma ventana al patio durante una semana y anotar cada ave que pudieran nombrar. La primera mañana registraron dos gorriones y una sombra apresurada que no identificaron.\n\nEl miércoles ya tenían un sistema: una persona miraba, otra escribía, y solo contaban un ave si al menos dos compañeros estaban de acuerdo. La sombra desconocida volvió y se quedó el tiempo suficiente para verle el dorso gris y el vientre claro. Era una paloma.\n\nEl viernes hicieron un cuadro sencillo. Los gorriones venían a menudo. La paloma vino dos veces. Un ave azul brillante vino una vez y no se quedó.\n\nColgaron el cuadro junto a la ventana, con una nota que decía que era un comienzo, no una lista completa. El patio, escribieron, todavía podía sorprenderlos.", "art": "birdWindow", "release101": 0, "q": [["¿Qué intentaba hacer la clase?", ["Contar y nombrar aves en una ventana", "Cazar aves", "Pintar el patio"], 0], ["¿Cómo nombraron al final la sombra?", ["Se quedó el tiempo suficiente para ver sus colores", "Adivinaron por un canto", "La persiguieron"], 0], ["¿Qué escribieron junto al cuadro?", ["Que era un comienzo, no una lista completa", "Que no vendrían más aves", "Que la ventana debía quedar cerrada"], 0]], "talk": ["¿Por qué necesitaban que dos compañeros estuvieran de acuerdo?", "¿Qué decía la nota del cuadro?"], "coach": ["Palabras: censo, identificar, patio.", "Comenten cómo esperar les ayudó a nombrar la sombra."]});
STORIES101.es.push({"id": "d101_es_3_02", "grade": 3, "t": "Una receta a cuatro manos", "text": "La receta de pan de la abuela estaba en una ficha tan usada que algunas palabras se habían borrado. Todavía decía «agua tibia» y «una pizca de sal», pero la cantidad de harina era una mancha pálida.\n\nElena sostenía el bol. La abuela acercó la ficha a la luz y recordó en voz alta: bastante harina para que la masa se despegara de los lados, no tanta que se sintiera seca.\n\nFueron añadiendo harina poco a poco y se turnaron para tocar la masa. Cuando a las dos les pareció bien, pararon.\n\nDespués, Elena copió una ficha nueva. Escribió las palabras antiguas y luego una línea nueva: «Añade harina hasta que se sienta lista, y pide que alguien más la toque». El olor de la cocina era el de siempre.", "art": "twoHands", "release101": 1, "q": [["¿Qué le había pasado a la ficha?", ["Algunas palabras se habían borrado", "La habían horneado", "Estaba en un código secreto"], 0], ["¿Cómo supieron cuándo dejar de añadir harina?", ["La masa les pareció bien a las dos", "Usaron un reloj", "Adivinaron una vez y se fueron"], 0], ["¿Qué añadió Elena a la ficha nueva?", ["Una línea sobre tocar la masa juntas", "Un dibujo de un autobús", "Una lista de aves"], 0]], "talk": ["¿Por qué no pudieron seguir solo los números?", "¿Qué línea nueva escribió Elena?"], "coach": ["Palabras: receta, borrado, mancha, masa.", "Si preparan algo, noten que «suficiente» a veces también se siente."]});
STORIES101.es.push({"id": "d101_es_3_03", "grade": 3, "t": "El carné olvidado", "text": "Jonás llegó al mostrador con una pila de libros y el bolsillo vacío. Su carné de la biblioteca estaba en casa, todavía en el gancho de la puerta.\n\nLa bibliotecaria no lo regañó. Apartó los libros y le explicó cómo funcionaba una reserva: los libros esperarían a su nombre unos días, y nadie más se los llevaría mientras tanto.\n\nJonás volvió a casa sin pila en los brazos y con un papelito en la mano. Encontró el carné exactamente donde lo había dejado.\n\nA la tarde siguiente regresó, mostró el carné y los mismos libros estaban esperando. Empezó una costumbre pequeña: revisar el bolsillo en los escalones, antes de entrar.", "art": "libraryCard", "release101": 2, "q": [["¿Qué había olvidado Jonás?", ["Su carné de la biblioteca", "El nombre de la bibliotecaria", "Cómo leer"], 0], ["¿Qué es una reserva en este cuento?", ["Los libros esperan a tu nombre unos días", "La biblioteca cierra", "Hay que comprar los libros"], 0], ["¿Qué empezó a hacer Jonás?", ["Revisar el bolsillo en los escalones", "Dejar el carné en la escuela", "Dejar de ir"], 0]], "talk": ["¿Qué hizo la bibliotecaria en vez de mandarlo con las manos vacías?", "¿Qué costumbre empezó Jonás?"], "coach": ["Palabras: mostrador, reserva, costumbre.", "Hablen de una vez que un plan tuvo que cambiar y aún así algo funcionó."]});
STORIES101.es.push({"id": "d101_es_3_04", "grade": 3, "t": "El lado tibio de la piedra", "text": "En un paseo fresco de mañana, Imani y su tío se sentaron en un muro bajo. Un lado de una piedra grande estaba fresco y gris. El lado que miraba al sol estaba un poco tibio.\n\nImani pensó en ello. La piedra no había hecho su propio calor. Había guardado algo de la luz de antes, como una taza gruesa guarda el té tibio cuando la tetera ya está apagada.\n\nTocaron una piedra más pequeña cerca. Ya estaba más cerca de la temperatura del aire. El tío dijo que las cosas delgadas cambian más rápido, y las gruesas tardan más en calentarse o enfriarse.\n\nDe vuelta a casa, Imani tocó la tierra oscura del jardín y el camino claro. No buscaba una favorita. Estaba practicando fijarse.", "art": "warmStone", "release101": 3, "q": [["¿De dónde venía el calor de la piedra?", ["De la luz del sol que había guardado", "De un fuego dentro", "De la luna"], 0], ["¿Cómo se sentía la piedra pequeña?", ["Más cerca de la temperatura del aire", "Hirviendo", "Helada del todo"], 0], ["¿Qué estaba practicando Imani?", ["Fijarse", "Tirar piedras a la gente", "Nombrar cada insecto"], 0]], "talk": ["¿Por qué un lado de la piedra estaba tibio?", "¿Por qué la piedra pequeña se sentía distinta?"], "coach": ["Palabras: ligeramente, temperatura, tierra.", "Pueden tocar un alféizar al sol y otro a la sombra, con cuidado, y comparar."]});
STORIES101.es.push({"id": "d101_es_3_05", "grade": 3, "t": "La parada de noche", "text": "El último autobús llegaba en diez minutos. Noor esperaba con su papá bajo el refugio. Unas gotas sonaron en el techo y luego cesaron. La calle estaba tan quieta que oían una radio en una cocina lejana.\n\nLlegó una vecina y preguntó si esa era la parada del camino al lago. Papá dijo que sí, y hicieron un poco más de sitio en el banco.\n\nCuando vino el autobús, sus luces eran cálidas y bajas, no intensas. Los tres subieron. Noor pulsó el timbre una parada antes, por accidente, y se lo dijo al conductor, que sonrió y contestó que la siguiente estaba bien.\n\nEn casa, Noor escribió una línea en su cuaderno: la noche se sentía grande, y las personas en ella habían sido amables de modos pequeños.", "art": "nightStop", "release101": 4, "q": [["¿Quién esperaba con Noor?", ["Su papá", "Nadie", "Una persona desconocida"], 0], ["¿Qué hicieron por la vecina?", ["Dijeron que era la parada correcta y hicieron sitio", "Le pidieron que se fuera", "Se escondieron del autobús"], 0], ["¿Qué hizo el conductor cuando Noor pulsó el timbre antes de tiempo?", ["Dijo que la siguiente parada estaba bien", "Se fue sin ellos", "Apagó las luces"], 0]], "talk": ["¿Cómo ayudaron a la vecina?", "¿Qué quiso recordar Noor?"], "coach": ["Palabras: refugio, llegada, accidente. La familia está junta todo el tiempo.", "Noten las amabilidades pequeñas: sitio en el banco, un conductor paciente."]});
STORIES101.es.push({"id": "d101_es_4_01", "grade": 4, "t": "El mapa de las estrellas fugaces", "text": "Después de una noche clara de agosto, algunos compañeros llegaron a la escuela hablando de rayas de luz. Algunos las llamaban estrellas fugaces. Su profesor de ciencias extendió un mapa sencillo del cielo sobre la mesa y explicó que esas rayas eran meteoros: trocitos de roca del espacio que se calientan al atravesar el aire de la Tierra.\n\nNadie de la clase había mirado la misma parte del cielo. Marcaron sus direcciones aproximadas en un papel compartido: sobre el depósito de agua, encima de las colinas del oeste, cerca del planeta brillante que había salido temprano.\n\nLas marcas no formaron una sola línea. Quedaron esparcidas, lo cual encajaba con lo que había dicho el profesor: en una lluvia, los meteoros pueden parecer venir de una región del cielo, pero cada trayectoria es suya.\n\nDejaron el mapa en la pared una semana, con un crédito cuidadoso a la idea, no a un solo observador. La siguiente noche clara, dos estudiantes salieron con sus familias y miraron sin intentar terminar el mapa. Mirar, decidieron, ya era una forma de guardar.", "art": "fallenStars", "release101": 0, "q": [["¿Qué eran las rayas de luz?", ["Meteoros que se calientan en el aire", "Estrellas que se caen del cielo para siempre", "Solo luces de aviones al aterrizar"], 0], ["¿Por qué las marcas estaban en sitios distintos?", ["Habían mirado partes distintas del cielo", "El mapa estaba roto", "Estaban inventando trayectorias"], 0], ["¿Qué hicieron dos estudiantes la siguiente noche clara?", ["Miraron con sus familias sin intentar terminar el mapa", "Intentaron recoger meteoros en frascos", "Apagaron todas las farolas"], 0]], "talk": ["¿Qué son las «estrellas fugaces» en este cuento?", "¿Por qué las marcas no formaron una sola línea?"], "coach": ["Palabras: meteoros, aproximado, región, observador.", "Si salen de noche, miren juntos y con calma: no hace falta atrapar cada raya."]});
STORIES101.es.push({"id": "d101_es_4_02", "grade": 4, "t": "Una carta en dos lenguas", "text": "El abuelo de Sofía le escribió una carta en español, con letra firme. En la escuela, Sofía usaba el inglés a diario, y algunas frases le pedían ir más despacio.\n\nNo se apresuró a una traducción perfecta. Leyó cada línea dos veces, una por el sonido y otra por el sentido, y armó una columna estrecha de palabras que quería preguntar. Algunas eran fáciles: cielo, mesa, domingo. Una frase, con calma, ya la usaba en casa.\n\nEl domingo lo llamó. Revisaron juntos la columna, y él le contó por qué había elegido una palabra y no otra. Luego ella contestó, primero en inglés, y después intentó tres oraciones en español, dejando un poco de espacio bajo cada una.\n\nÉl respondió a esas oraciones sin corregir cada letra. Respondió a las ideas. Sofía guardó las dos cartas en el mismo sobre, porque iban juntas.", "art": "twoLanguages", "release101": 1, "q": [["¿Qué hizo Sofía en vez de apresurar una traducción perfecta?", ["Leyó dos veces y armó una columna de preguntas", "Tiró la carta", "Pidió a un desconocido que la reescribiera"], 0], ["¿Qué hicieron el domingo?", ["Revisaron las palabras juntos por teléfono", "Olvidaron la carta", "Tradujeron un libro entero"], 0], ["¿Cómo contestó él a sus oraciones en español?", ["Respondió a las ideas, sin corregir cada letra", "Se negó a leerlas", "Le puso una nota"], 0]], "talk": ["¿Cómo leyó Sofía la carta?", "¿Qué contestó el abuelo: la ortografía o las ideas?"], "coach": ["Palabras: traducción, frase, columna.", "Si en casa hay dos lenguas, noten cómo el sentido puede viajar aunque una oración aún esté aprendiendo su forma."]});
STORIES101.es.push({"id": "d101_es_4_03", "grade": 4, "t": "Los ayudantes callados del jardín", "text": "Los tomates del jardín comunitario se veían cansados, aunque la gente los regaba a menudo. Una voluntaria llamada Priya invitó a unos niños a mirar la tierra, no solo las hojas.\n\nBajo un puñado levantado encontraron oscuridad húmeda, una raíz pálida y dos lombrices que se alejaban despacio de la luz. Priya dijo que las lombrices y otras vidas pequeñas ayudan a mezclar aire y hojas sobrantes con la tierra, y eso ayuda a las plantas a beber y a sostenerse.\n\nEl grupo decidió poner una capa de hojas secas alrededor de las plantas, dejando espacio en cada tallo, y pisar los senderos en vez de los bancales. También acordaron no llevarse las lombrices.\n\nDos semanas después, la tierra se sentía más suelta bajo un dedo cuidadoso. Los tomates no eran mágicamente altos, pero se veían menos cansados. Priya escribió un letrero pequeño: «Los ayudantes que quizá no veas siguen trabajando. Por favor, camina por el sendero».", "art": "quietHelpers", "release101": 2, "q": [["¿Qué les pidió Priya que miraran?", ["La tierra, no solo las hojas", "Solo la cerca del jardín", "Las nubes"], 0], ["¿Cómo ayudan las lombrices en este cuento?", ["Ayudan a mezclar aire y hojas sobrantes con la tierra", "Riegan de noche con regaderas minúsculas", "Asustan a los tomates para que crezcan"], 0], ["¿Qué acordó el grupo?", ["Poner hojas, ir por los senderos y dejar las lombrices", "Llevarse las lombrices a casa", "Arrancar los tomates"], 0]], "talk": ["¿Qué miraron además de las hojas?", "¿Por qué no se llevaron las lombrices?"], "coach": ["Palabras: tierra, lombrices, bancales, suelta.", "Si visitan un jardín, quédense en los senderos y miren sin llevarse a los seres vivos."]});
STORIES101.es.push({"id": "d101_es_4_04", "grade": 4, "t": "El bebedero helado", "text": "Después de una noche muy fría, el agua del bebedero del patio se había vuelto una tapa lisa de hielo. Por la mañana, dos gorriones se posaron en el borde, dieron saltitos y se fueron.\n\nEl papá de Nadia no echó agua hirviendo sobre el hielo. Trajo un plato bajo con agua fresca y lo puso junto al bebedero, en un sitio abierto y tranquilo donde los gatos no pudieran esconderse con facilidad. Luego llevaron el cuenco helado adentro para que se descongelara despacio en el fregadero.\n\nNadia preguntó por qué el plato nuevo era bajo. Papá dijo que las aves necesitan posarse y irse con facilidad, y el agua honda se lo pone más difícil.\n\nPor la tarde, el bebedero original ya era líquido. Lo llenaron otra vez y metieron el plato extra, para no dejar un charco por la noche que se helara como una trampa. Los gorriones volvieron cerca del anochecer, bebieron y se fueron al seto.", "art": "birdBath", "release101": 3, "q": [["¿Qué le había pasado al bebedero?", ["El agua se había helado", "Se había volado", "Estaba lleno de muñecos de nieve"], 0], ["¿Qué les ofrecieron a las aves en vez de hervir el hielo?", ["Un plato bajo con agua fresca al lado", "Nada hasta el verano", "Una botella cerrada"], 0], ["¿Por qué metieron después el plato extra?", ["Para que no se helara de noche de un modo que pudiera atrapar", "Para esconderlo de los gorriones", "Porque los platos no pueden mojarse"], 0]], "talk": ["¿Por qué no usaron agua hirviendo?", "¿Por qué el plato era bajo, y por qué no quedó afuera toda la noche?"], "coach": ["Palabras: bebedero, descongelar, bajo, seto.", "La amabilidad con los animales aquí es práctica y calmada: sin perseguir ni atrapar."]});
STORIES101.es.push({"id": "d101_es_4_05", "grade": 4, "t": "El cuento que contaron dos veces", "text": "Para un trabajo de clase, Amir y Lina tenían que contar una historia familiar de dos modos: una vez como se la habían contado, y otra solo con las partes que podían sostener.\n\nEl primer relato estaba lleno de color. Un tío abuelo había cruzado un puente largo en una tormenta, y el viento «casi lo lleva al río». Era una buena frase para oír.\n\nEn el segundo relato, preguntaron a la madre de Amir qué recordaba que le hubieran contado, y qué había visto ella misma. Había visto al tío abuelo llegar a casa mojado, riendo y cansado. No había visto el puente. La tormenta, dijo, era real; el «casi» era la forma que toma un cuento cuando pasa de una persona a otra.\n\nPresentaron las dos versiones, una al lado de la otra, sin llamar mentira a ninguna. La clase habló de cómo un relato puede guardar un sentimiento y aún dejar sitio para lo que nadie presente puede probar. Amir escribió que ambos relatos pertenecían a la familia, por razones distintas.", "art": "toldTwice", "release101": 4, "q": [["¿Qué les pidieron a Amir y a Lina?", ["Contar una historia familiar de dos modos", "Inventar una tormenta", "Construir un puente"], 0], ["¿Qué había visto ella misma la madre de Amir?", ["Al tío abuelo llegar mojado, riendo y cansado", "El viento levantándolo del puente", "Nada en absoluto"], 0], ["¿Cómo presentaron las dos versiones?", ["Una al lado de la otra, sin llamar mentira a ninguna", "Tiraron la primera", "Pretendieron que eran iguales"], 0]], "talk": ["¿En qué se diferenciaba el segundo relato?", "¿Por qué no llamaron mentira al primero?"], "coach": ["Palabras: sostener (como evidencia), versión, probar.", "Es una lección suave sobre la memoria y las pruebas, no sobre pillar a alguien."]});
STORIES101.es.push({"id": "d101_es_5_01", "grade": 5, "t": "La luz que llegó al pozo", "text": "El museo del pueblo conservaba un pozo seco y cubierto en su patio, como parte de una casa antigua. Un letrero pedía que los visitantes no tiraran monedas. Aun así, el fondo solo parecía oscuridad.\n\nUn grupo de quinto estaba estudiando cómo viaja la luz. Su maestra llevó un espejo pequeño y una linterna y, con permiso, inclinaron el haz en el espejo hasta que un círculo pálido apareció en el ladrillo del fondo. El polvo hizo un poco visible el camino de la luz en el aire.\n\nMidiendo de modo aproximado, vieron cómo el ángulo que elegían cambiaba el lugar del círculo. Alguien dijo que parecía trampa, usar una herramienta para ver lo que los ojos no podían. Otra estudiante dijo que parecía hacer una pregunta mejor.\n\nApagaron la linterna y dejaron el pozo otra vez en la oscuridad. En sus notas escribieron que la oscuridad del fondo no había significado vacío. Había significado que la luz que traían todavía no estaba en el lugar adecuado.", "art": "wellLight", "release101": 0, "q": [["¿Qué apareció cuando inclinaron la luz?", ["Un círculo pálido en el ladrillo del fondo", "Una moneda que debían tirar", "Un segundo sol"], 0], ["¿Qué hizo un poco visible el camino de la luz?", ["El polvo en el aire", "La pintura", "Una radio"], 0], ["¿Qué escribieron sobre la oscuridad?", ["Que no había significado vacío", "Que el pozo debía llenarse de tierra", "Que la luz nunca puede bajar"], 0]], "talk": ["¿Qué mostraron el espejo y la linterna?", "¿Qué dijeron sus notas sobre la oscuridad?"], "coach": ["Palabras: patio, ángulo, visible, vacío.", "Un momento suave de ciencia: las herramientas ayudan a mirar, y luego se deja el lugar como estaba."]});
STORIES101.es.push({"id": "d101_es_5_02", "grade": 5, "t": "Lo que guardó el río", "text": "Un sábado de limpieza, un club de ciencias recorrió un tramo corto de orilla con guantes y bolsas. Les habían pedido llevarse la basura y dejar las plantas vivas y las piedras naturales sueltas.\n\nCerca de una curva, Marisol encontró una forma lisa y pesada, a medio enterrar en el barro. Al principio parecía una roca oscura y ovalada. Cuando la enjuagó en un cubo, apareció un dibujo en espiral, en relieve y regular. Su mentor dijo que podría ser un fósil —una huella o un resto de algo que vivió hace mucho—, pero que una identificación cuidadosa correspondía al centro de naturaleza, no a una mochila.\n\nLo fotografieron donde estaba, marcaron el sitio en un croquis sencillo y, con el mentor, lo llevaron solo hasta el mostrador del centro, junto con las bolsas de basura del día.\n\nUna semana después llegó una nota: era un caparazón fósil, común en la roca antigua de aquel valle, y se quedaría en un cajón que los estudiantes podían visitar. A Marisol le gustó que el río lo hubiera guardado tanto tiempo, y que su trabajo hubiera sido fijarse, no poseerlo.", "art": "riverKept", "release101": 1, "q": [["¿Qué debían llevarse de la orilla?", ["La basura, no las plantas vivas ni las piedras naturales sueltas", "Todas las piedras que les gustaran", "Peces"], 0], ["¿Qué les hizo pensar que podría ser un fósil?", ["Una espiral regular en relieve, después de enjuagar", "Brillaba en la oscuridad", "Hacía un sonido"], 0], ["¿Dónde terminó el fósil?", ["En un cajón del centro de naturaleza que se podía visitar", "En la mochila de Marisol para siempre", "Lo devolvieron sin dejar constancia"], 0]], "talk": ["¿Por qué no lo metieron enseguida en una mochila?", "¿Qué fue del fósil?"], "coach": ["Palabras: orilla, fósil, identificación, mentor.", "Recoger de la naturaleza se trata con cuidado: fijarse, preguntar y dejar que un lugar adecuado lo conserve."]});
STORIES101.es.push({"id": "d101_es_5_03", "grade": 5, "t": "El día que la clase midió el silencio", "text": "En el aula de música había un problema que no era un instrumento roto. Después del almuerzo, el ruido del pasillo se colaba bajo la puerta, y las piezas suaves costaban de oír.\n\nEn vez de quejarse solamente, la clase intentó una medición. Eligieron tres momentos del día y, con un medidor sencillo que la maestra ya tenía, anotaron lo alto que sonaba el pasillo justo afuera y justo adentro. También anotaron si la puerta estaba del todo cerrada.\n\nLos números no eran perfectos, pero el patrón era claro. Media tarde era lo más ruidoso. Una puerta bien cerrada ayudaba un poco. Una manta doblada a lo largo de la base de la puerta, que el conserje aprobó, ayudaba más.\n\nEscribieron un informe breve para la dirección, con su cuadro y un agradecimiento al conserje. El pasillo seguía siendo un pasillo. El aula, en cambio, podía volver a sostener una pieza suave, y la clase tenía un método para otras preguntas ruidosas.", "art": "measureSilence", "release101": 2, "q": [["¿Qué problema tenía el aula de música?", ["El ruido del pasillo se colaba y costaba oír las piezas suaves", "Faltaban todos los instrumentos", "La maestra canceló la música"], 0], ["¿Qué hicieron además de quejarse?", ["Midiaron el volumen a tres horas del día", "Gritaron más fuerte", "Mudaron la escuela"], 0], ["¿Qué ayudó más que solo cerrar la puerta?", ["Una manta doblada en la base, con aprobación", "Quitar la puerta", "Convertir el pasillo en un escenario"], 0]], "talk": ["¿Qué midieron, y cuándo?", "¿Qué ayudó de verdad al aula?"], "coach": ["Palabras: colarse, medidor, patrón, conserje.", "Es resolución de problemas con evidencias, no una campaña contra nadie."]});
STORIES101.es.push({"id": "d101_es_5_04", "grade": 5, "t": "Una órbita que pudimos dibujar", "text": "En Mirar al cielo, la clase ya había puesto los planetas en su orden real desde el Sol. Ahora la maestra hizo una pregunta más difícil y más callada: si la Tierra vale uno, ¿cómo mostrar el tamaño de Júpiter sin comprimir todo el sistema solar en una página?\n\nProbaron dos dibujos. El primero ponía los ocho planetas en fila, a un tamaño que cupiera en el papel. Júpiter parecía solo un poco más grande que la Tierra, y eso se sentía injusto cuando leyeron una comparación de la NASA: si Júpiter fuera una cáscara hueca, cabrían dentro unas mil Tierras. Si la Tierra fuera del tamaño de una uva, Júpiter sería más o menos del tamaño de un balón de básquetbol.\n\nEl segundo dibujo mostraba solo la Tierra y Júpiter, con la Tierra como un círculo pequeño y Júpiter como un círculo que casi llegaba al borde de un cartel. Los demás planetas estaban nombrados en una lista al lado, con una nota de que la distancia es otra clase de inmensidad y necesitaba otro dibujo.\n\nColgaron ambos carteles y escribieron, bajo el segundo, de dónde venía la comparación. Algunos estudiantes dijeron que el primer cartel seguía siendo útil para el orden. El segundo, dijeron, era para el respeto: para no hacer que un gigante parezca ordinario solo porque el papel es pequeño.", "art": "orbitDraw", "release101": 3, "q": [["¿Qué comparación leyeron sobre Júpiter?", ["Cabían dentro unas 1.000 Tierras", "Es más pequeño que la Luna", "Es el planeta más cercano al Sol"], 0], ["¿Qué mostraba el segundo dibujo?", ["Solo la Tierra y Júpiter, con una diferencia de tamaño más justa", "Los ocho planetas a su distancia verdadera", "Un mapa de su pueblo"], 0], ["¿Por qué conservar también el primer cartel?", ["Seguía siendo útil para mostrar el orden", "Tenía mejores colores", "La maestra exigía dos errores"], 0]], "talk": ["¿Por qué el primer dibujo se sentía injusto?", "¿Qué dos clases de inmensidad separaron?"], "coach": ["Palabras: órbita, comparación, distancia, escala. El número viene de la NASA y se plantea como comparación, no como una cifra para memorizar.", "Después de leer, pueden abrir Mirar al cielo en la aplicación y hablar de tamaño frente a orden."]});
STORIES101.es.push({"id": "d101_es_5_05", "grade": 5, "t": "El banco de las dos placas", "text": "Un banco del parque tenía dos placas pequeñas, una en cada extremo, con dos nombres distintos y dos años separados por veinte años. Kenji se sentó con su tía, leyó las dos y miró los árboles como si pudieran explicar.\n\nUn voluntario del parque, que barría el camino, los vio leer y les contó lo que decía el archivo del cobertizo. La primera placa era de una familia a la que le gustaba esta vista del estanque. Años después, cuando cambiaron los listones del banco, una segunda familia pidió añadir una segunda placa en vez de quitar la primera.\n\nEl voluntario dijo que la regla del parque era sencilla: una reparación no debe borrar un recuerdo si hay sitio para ambos. Kenji pasó la mano por los listones nuevos y el brazo de metal más antiguo.\n\nLe dijo a su tía que había pensado que un nombre tendría que ganar. Le gustaba más la otra idea: que un lugar puede guardar dos agradecimientos, y que una reparación puede quedar a la vista sin fingir que el banco siempre había sido nuevo.", "art": "twoPlaques", "release101": 4, "q": [["¿Qué vio Kenji en el banco?", ["Dos placas con nombres y años distintos", "Un mapa escondido", "Un columpio roto atado al banco"], 0], ["¿Por qué se añadió la segunda placa?", ["Una segunda familia pidió añadirla cuando cambiaron los listones, en vez de quitar la primera", "La primera placa había sido un error", "El voluntario necesitaba más metal"], 0], ["¿Qué regla describió el voluntario?", ["Una reparación no debe borrar un recuerdo si hay sitio para ambos", "En un parque solo se permite un nombre", "Los bancos viejos deben esconderse"], 0]], "talk": ["¿Por qué hay dos placas?", "¿Cuál era la regla del parque sobre reparar y recordar?"], "coach": ["Palabras: placas, listones, borrar, visible.", "Un cuento calmado sobre compartir un recuerdo, sin detenerse en la pérdida. Mantengan la conversación suave."]});
})();
